option.value:
html,
body {
  min-height: 100%;
  max-width: 100%;
  overflow-x: hidden;
  overflow-y: auto;
}

body {
  margin: 0;
  font-family: var(--font-body), system-ui, -apple-system, "Segoe UI", Arial, sans-serif;
  font-weight: 300;
  color: var(--color-text);
  background: var(--color-secondary);
}

:root {
  /* ── Palette ── */
  --color-primary: #C17855;   /* terracotta */
  --color-secondary: #F5EBE0; /* warm cream */
  --color-accent: #5A6C57;    /* deep olive */
  --color-text: #2C2C2C;      /* charcoal */
  --color-white: #FFFFFF;

  /* Hero-vibe dark surfaces (warm espresso) */
  --color-hero-surface: #14110f;
  --color-hero-surface-2: #1b1714;
  --color-hero-accent: #c9a96e; /* warm gold */

  /* Hovers */
  --color-accent-hover: #4F5F4C;

  /* Font variables (populated at runtime by next/font classes) */
  --font-heading: "Cormorant Garamond";
  --font-body: "Montserrat";

  --focus-ring: 0 0 0 3px rgba(90, 108, 87, 0.35);
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading), ui-serif, Georgia, "Times New Roman", Times, serif;
  font-weight: 600;
}

a {
  color: var(--color-accent);
}

a:hover {
  color: var(--color-accent-hover);
}

:where(a, button, [role="button"], input, textarea, select):focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: 4px;
}

.pageBanner {
  position: relative;
  width: 100%;
  height: clamp(360px, 55vw, 620px);
  display: grid;
  grid-template-rows: auto 1fr;
  align-items: start;
  text-align: center;
  overflow: hidden;

  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

/* Dark overlay */
.pageBanner::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.52);
  z-index: 0;
}

/* All direct children above the overlay */
.pageBanner > * {
  position: relative;
  z-index: 1;
}

.pageBannerLogo {
  width: clamp(60px, 8vw, 96px);
  height: auto;
  padding-top: clamp(24px, 4vw, 48px);
  filter: drop-shadow(0 0 18px rgba(210, 170, 80, 0.45));
  /* stays at top of grid row 1 */
  align-self: start;
  justify-self: center;
}

/* Wrapper that centers kicker + title in the remaining space */
.pageBannerContent {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
}

.pageBannerKicker {
  margin: 0 0 18px;
  font-size: 15px;
  letter-spacing: 0.28em;
  font-weight: 600;
  text-transform: uppercase;
  color: rgba(210, 170, 80, 0.9);
  font-family: var(--font-body), "Gill Sans", Optima, system-ui, sans-serif;

  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
}

.pageBannerKicker::before,
.pageBannerKicker::after {
  content: "";
  display: block;
  width: 48px;
  height: 1px;
  background: rgba(210, 170, 80, 0.6);
}

.pageBannerTitle {
  margin: 0;
  font-size: clamp(64px, 10vw, 124px);
  line-height: 1.0;
  letter-spacing: 0.04em;
  font-weight: 400;
  color: #ffffff;
  font-family: var(--font-heading), "Cormorant Garamond", ui-serif, Georgia, "Times New Roman", serif;
  text-shadow: 0 2px 32px rgba(0, 0, 0, 0.55);
}

.pageBanner--about  { background-image: url("/images/home/img_3.webp"); }
.pageBanner--menu   { background-image: url("/images/home/img_1.webp"); }
.pageBanner--wine   { background-image: url("/images/wine/wine-barrel.webp"); }

